    if l == r:
        return 0
    if l == 1:
        return min(solve(n, pos, l + 1, r), solve(n, pos, l, r - 1))
    if r == n:
        return min(solve(n, pos, l, r - 1), solve(n, pos, l + 1, r))
    return min(solve(n, pos, l + 1, r), solve(n, pos, l, r - 1)) + 1

