def solve_query():
    n, x = map(int, input().split())
    blows = []
    for _ in range(n):
        d, h = map(int, input().split())
        blows.append((d, h))

    queue = deque([(x, 0)])
    visited = set()
    while queue:
        heads, blows_used = queue.popleft()
        if heads == 0:
            return blows_used
        if (heads, blows_used) in visited:
            continue
        visited.add((heads, blows_used))
        for i, (d, h) in enumerate(blows):
            new_heads = max(0, heads - min(d, heads)) + h
            if new_heads > 0:
                queue.append((new_heads, blows_used + 1))
    return -1

