def ways_to_reach(n, k, S, cubes):
    cube_freq = {}
    for i, cube in enumerate(cubes):
        if cube in cube_freq:
            cube_freq[cube] += 1
        else:
            cube_freq[cube] = 1

    freq_dict = {}
    for cube, freq in cube_freq.items():
        freq_dict[freq] = freq_dict.get(freq, 0) + freq

    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i - 1][j]
            if cubes[i - 1] > 0:
                dp[i][j] += dp[i - 1][j - 1] * freq_dict[cubes[i - 1]]

    res = 0
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if dp[i][j] == S:
                res += 1

    return res


