from collections import defaultdict

def solve(N, A):
    graph = defaultdict(list)
    for i in range(N):
        for j in range(N):
            for dx, dy in [(1, 2), (2, 1), (-1, 2), (2, -1), (1, -2), (-2, 1), (-1, -2), (-2, -1)]:
                x, y = i + dx, j + dy
                if 0 <= x < N and 0 <= y < N:
                    graph[(i, j)].append((x, y))

    def dfs(node, visited):
        if len(visited) == N * N:
            return 0, 0
        min_steps, min_replacements = float('inf'), float('inf')
        for neighbor in graph[node]:
            if neighbor not in visited:
                steps, replacements = dfs(neighbor, visited | {neighbor})
                if steps + A[neighbor[0]][neighbor[1]] < min_steps or (steps + A[neighbor[0]][neighbor[1]] == min_steps and replacements < min_replacements):
                    min_steps, min_replacements = steps + A[neighbor[0]][neighbor[1]], replacements
        return min_steps, min_replacements

    return dfs((0, 0), {(0, 0)})

