def pack_presents(n, m):
    # Create a dictionary to keep track of the number of ways to pack each kind of present
    # into each box
    packings = {}
    for i in range(n):
        packings[i] = 0

    # Iterate over the boxes and pack the presents in a way that satisfies Alice's rules
    for i in range(m):
        # Initialize a set to keep track of the kinds of presents that have been packed into each box
        box_contents = set()
        # Iterate over the presents and pack them into the boxes in a way that satisfies Alice's rules
        for j in range(n):
            if packings[j] == 0:
                # If the present of kind j has not been packed into any box yet, pack it into the current box
                box_contents.add(j)
                packings[j] = 1
            else:
                # If the present of kind j has already been packed into a box, make sure it's not packed into the same box again
                if box_contents.count(j) > 0:
                    packings[j] = 0
                else:
                    box_contents.add(j)

    # Calculate the number of ways to pack the presents by multiplying the number of boxes by the number of kinds of presents
    # that are packed into each box, and then dividing by 10^9+7
    return m * len(packings) // (10**9 + 7)

