        sign, subnet = item[0], item[1:]
        if sign == '-':
            start, end = subnet_to_range(subnet)
            blacklist_set.update(range(start, end))
        else:
            whitelist_set.add(int(subnet.replace('.', '')))

    # Remove whitelist addresses from blacklist set
    blacklist_set -= whitelist_set

