    queue = [(start, 0)]  # (node, distance)
    visited = set([start])

    while queue:
        node, distance = queue.pop(0)

        if node == end:
            return distance

        for neighbour in graph[node]:
            if neighbour not in visited:
                visited.add(neighbour)
                queue.append((neighbour, distance + 1))

    return -1  # No path found


