                if m - y < i - x + 1:
                    break
            for i in range(x - 1, -1, -1):
                grid[i][y] = True
                if i - x < y + 1:
                    break
            for i in range(y + 1, m):
                grid[x][i] = True
                if i - y < x + 1:
                    break
            for i in range(x - 1, -1, -1):
