def min_purchases(n, m, elements):
    table = set()
    for r, c in elements:
        table.add((r, c))

    missing = set()
    for r in range(1, n+1):
        for c in range(1, m+1):
            if (r, c) not in table:
                missing.add((r, c))

    queue = list(missing)
    purchases = 0

    while queue:
        r, c = queue.pop(0)
        if not can_produce(n, m, table, r, c):
            purchases += 1
            continue

        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr <= n and 0 <= nc <= m and (nr, nc) not in table:
                    queue.append((nr, nc))
                    table.add((nr, nc))

    return purchases

def can_produce(n, m, table, r, c):
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        if 0 <= r+dr <= n and 0 <= c+dc <= m and (r+dr, c+dc) in table:
            return True
    return False

