def count_distinct_strings(N, S):
    # Initialize a set to store the distinct strings
    distinct_strings = set()

    # Perform the operations on S
    for _ in range(N):
        # Choose an index i such that S_i != S_{i+1}
        i = choose_index(S)

        # Replace S_i with the character that is different from both S_i and S_{i+1}
        new_char = choose_char(S, i)

        # Remove S_{i+1} from S
        S = remove_char(S, i+1)

        # Add the new string to the set of distinct strings
        distinct_strings.add(S)

    # Return the number of distinct strings modulo (10^9+7)
    return len(distinct_strings) % (10**9 + 7)

def choose_index(S):
    # Choose an index i such that S_i != S_{i+1}
    for i in range(1, len(S) - 1):
        if S[i] != S[i+1]:
            return i
    return -1

def choose_char(S, i):
    # Choose the character that is different from both S_i and S_{i+1}
    for char in ['A', 'B', 'C']:
        if S[i] != char and S[i+1] != char:
            return char
    return None

def remove_char(S, i):
    # Remove the character at index i from S
    return S[:i] + S[i+1:]

