                            parent[j] = node
                            stack.append((j, node))

    return -1 if min_cycle_length == sys.maxsize else min_cycle_length

def find_path(start, end, parent):
    path = []
    current = end
    while current != start:
        path.append(current)
            current = parent[current]
    path.append(start)
    return path[::-1]

