def solve_smally(t, n):
    # Create a dictionary to store the cost of moving each disk
    cost = {(i, j): t[i][j] for i in range(3) for j in range(3)}

    # Initialize the cost of moving all disks to the third rod
    cost[(3,)] = n * (n - 1) // 2

    # Iterate through all possible combinations of moving disks
    for i in range(n):
        for j in range(n):
            # Calculate the cost of moving the current disk to the third rod
            cost[(i, j)] = min(cost[(i, j)], cost[(i, j + 1)] + cost[(i + 1, j)])

    # Return the minimum cost of moving all disks to the third rod
