def is_goal_achievable(s, x, y):
    # Split the instruction sequence into two parts: directions and distances
    directions = []
    distances = []
    current_direction = 0
    current_distance = 0
    for char in s:
        if char == 'F':
            current_distance += 1
        else:
            directions.append(current_direction)
            distances.append(current_distance)
            current_direction = (current_direction + 1) % 4
            current_distance = 0
    directions.append(current_direction)
    distances.append(current_distance)

    # Check if the total distance is reachable
    total_distance = sum(distances)
    if total_distance > len(s):
        return "No"

    # Check if the target coordinates are reachable
    if (total_distance % 2 == 0 and abs(x) % 2 != 0) or (total_distance % 2 != 0 and abs(x) % 2 == 0):
        return "No"

    # Check if the robot can reach the target coordinates
    x_reachable = is_coordinate_reachable(distances, directions, x)
    y_reachable = is_coordinate_reachable(distances, directions, y)

    if x_reachable and y_reachable:
        return "Yes"
    else:
        return "No"

def is_coordinate_reachable(distances, directions, target):
    n = len(distances)
    dp = {0: {0: True}}
    for i in range(n):
        new_dp = {}
        for x in dp:
            for y in dp[x]:
                new_dp[x + distances[i]] = {y + distances[i]: True}
                new_dp[x - distances[i]] = {y + distances[i]: True}
                new_dp[x] = {y + distances[i]: True}
                new_dp[x + distances[i]] = {y: True}
        dp = new_dp

    return target in dp or -target in dp

# Read input
