import sys
import itertools

def kruskal(edges, n):
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return
        if rank[px] < rank[py]:
            parent[px] = py
        else:
            parent[py] = px
            rank[px] += rank[py]

    result = []
    edges.sort(key=lambda x: x[2])

    for edge in edges:
        u, v, w = edge
        if find(u) != find(v):
            result.append(edge)
            union(u, v)
            if len(result) == n - 1:
                break

    return result

