import math

def factorial(n):
    if n == 0:
        return 1
    return math.factorial(n) % (10**9 + 7)

def dp(n):
    white = [[0] * 2 for _ in range(n)]
    black = [[0] * 2 for _ in range(n)]

    white[0][0] = 1
    black[0][1] = 1

    for i in range(1, n):
        white[i][0] = (white[i-1][0] + white[i-1][1]) % (10**9 + 7)
        white[i][1] = (white[i-1][0] + white[i-1][1] + black[i-1][0]) % (10**9 + 7)
        black[i][0] = (black[i-1][0] + black[i-1][1]) % (10**9 + 7)
        black[i][1] = (black[i-1][0] + black[i-1][1] + white[i-1][0]) % (10**9 + 7)

    return (white[n-1][0] * factorial(n) + white[n-1][1] * factorial(n-1)) % (10**9 + 7)

