                schedule[i] = exam
                exam_day = True
                break

        # If the current day is not an exam day, check if Petya can prepare for an exam
        if not exam_day:
            for exam, days in exam_days.items():
                if i in days and all(schedule[j] == 0 or schedule[j] == exam for j in days):
                    schedule[i] = exam
                    break
            else:
                schedule[i] = 0

    # Check if Petya can prepare and pass all exams
    if all(schedule[i] != 0 for i in range(n)):
        return schedule
    else:
