def is_palindromic(a):
    # check if the matrix is square
    if len(a)!= len(a[0]):
        return False

    # create a copy of the matrix
    matrix = [[x for x in row] for row in a]

    # check if the matrix is symmetric
    for i in range(len(matrix)):
        for j in range(i+1, len(matrix[0])):
            if matrix[i][j]!= matrix[j][i]:
                return False

    # reverse the rows of the matrix
    for i in range(len(matrix)//2):
        matrix[i], matrix[len(matrix)-i-1] = matrix[len(matrix)-i-1], matrix[i]

    # check if the transposed matrix is symmetric
    for i in range(len(matrix)):
        for j in range(i+1, len(matrix[0])):
            if matrix[i][j]!= matrix[j][i]:
                return False

    return True

# find all possible combinations of numbers that can be used to fill a matrix of size n x n
def find_combinations(n):
    # generate all possible combinations of numbers from 1 to n^2
    combinations = list(itertools.combinations_with_replacement(range(1, n**2+1), n))

    # filter out combinations that do not form a palindromic matrix
    return [c for c in combinations if is_palindromic(c)]

