def construct_binary_string(a, b, x):
    # Create a list to store the binary string
    s = []

    # Loop until the length of the binary string reaches the desired length
    while len(s) < a + b:
        # Check if there are enough zeroes and ones in the list
        if len(s) < a:
            # Add a zero to the list
            s.append(0)
        elif len(s) < b:
            # Add a one to the list
            s.append(1)
        else:
            # Check if there are enough unique indices where $s_i \ne s_{i + 1}$
            unique_indices = set()
            for i in range(len(s) - 1):
                if s[i] != s[i + 1]:
                    unique_indices.add(i)
            # Add enough ones to the list to fill the remaining positions
            while len(unique_indices) < x:
                s.append(1)
            # Remove the extra ones from the list
            s = [s[i] for i in unique_indices]

    return "".join(s)

