def lcm(a, b): return a // gcd(a, b) * b

def prime_factorization(n):
    factors = []
    i = 2
    while i * i <= n:
        if n % i: i += 1
        else:
            factors.append(i)
            n //= i
    if n > 1: factors.append(n)
    return factors

def smallest_number(divisors):
    g = 1
    for d in divisors: g = lcm(g, d)
    pfs = prime_factorization(g)
    return reduce(lambda x, y: x * (y[0] ** ((len(divisors) - divisors.count(y[0])) // (y[1] > 1)), pfs, 1)

